command:
$ErrorActionPreference='Continue'
Write-Output '--- LABELS-PER-CONTAINER ---'
foreach ($n in @('ollama','postgres','redis','open-webui','portainer','williamos-hermes-inference-proxy')) {
  $raw = & docker inspect $n --format '{{json .Config.Labels}}' 2>&1
  Write-Output "$n => $raw"
}
Write-Output '--- MODEL-STORE-F ---'
if (Test-Path 'F:\HermesData\ollama') { Write-Output 'F-EXISTS'; Get-ChildItem 'F:\HermesData\ollama' | Select-Object -ExpandProperty Name } else { Write-Output 'F-ABSENT' }
Write-Output '--- MODEL-STORE-D ---'
if (Test-Path 'D:\HermesData\ollama') { Write-Output 'D-EXISTS'; Get-ChildItem 'D:\HermesData\ollama' | Select-Object -ExpandProperty Name } else { Write-Output 'D-ABSENT' }
Write-Output '--- MANIFESTS-F ---'
if (Test-Path 'F:\HermesData\ollama\models\manifests') { Get-ChildItem 'F:\HermesData\ollama\models\manifests' -Recurse -File | ForEach-Object { $_.FullName.Replace('F:\HermesData\ollama\models\manifests\','') } }
Write-Output '--- BLOB-BYTES-F ---'
if (Test-Path 'F:\HermesData\ollama\models\blobs') { $m=(Get-ChildItem 'F:\HermesData\ollama\models\blobs' -File | Measure-Object -Sum Length); Write-Output "count=$($m.Count) bytes=$($m.Sum)" }
Write-Output '--- START-SCRIPT ---'
if (Test-Path 'C:\HermesLab\start-hermes.ps1') { Write-Output 'START-EXISTS'; (Get-FileHash 'C:\HermesLab\start-hermes.ps1' -Algorithm SHA256).Hash.ToLower() } else { Write-Output 'START-ABSENT' }
Write-Output '--- ENVFILE ---'
if (Test-Path 'C:\HermesLab\hermes\.env') { Write-Output '.env EXISTS' } else { Write-Output '.env ABSENT' }
Get-ChildItem 'C:\HermesLab\hermes' -Force | Select-Object -ExpandProperty Name
Write-Output '--- RC ---'
Write-Output "LASTEXITCODE=$LASTEXITCODE"
